begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select set_config('request.jwt.claims','{}',true);
insert into auth.users(id) values ('00000000-0000-4000-8000-000000009101'),('00000000-0000-4000-8000-000000009102'),('00000000-0000-4000-8000-000000009103'),('00000000-0000-4000-8000-000000009104'),('00000000-0000-4000-8000-000000009105'),('00000000-0000-4000-8000-000000009106');
insert into public.users(id) values ('00000000-0000-4000-8000-000000009101'),('00000000-0000-4000-8000-000000009102'),('00000000-0000-4000-8000-000000009103'),('00000000-0000-4000-8000-000000009104'),('00000000-0000-4000-8000-000000009105'),('00000000-0000-4000-8000-000000009106') on conflict do nothing;
insert into public.workspaces(id,name,personal,creator_id) values ('00000000-0000-4000-8000-000000009111','Synthetic legacy Meet',false,'00000000-0000-4000-8000-000000009101'),('00000000-0000-4000-8000-000000009112','Synthetic other workspace',false,'00000000-0000-4000-8000-000000009105');
insert into public.workspace_members(ws_id,user_id,type) values ('00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009101','MEMBER'),('00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009102','MEMBER'),('00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009103','MEMBER'),('00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009104','MEMBER'),('00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009106','GUEST') on conflict do nothing;
update public.workspace_default_permissions set enabled=false where ws_id='00000000-0000-4000-8000-000000009111' and permission='admin';
insert into public.workspace_roles(id,ws_id,name) values ('00000000-0000-4000-8000-000000009113','00000000-0000-4000-8000-000000009111','Synthetic Meet admin');
insert into public.workspace_role_permissions(ws_id,role_id,permission,enabled) values ('00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009113','admin',true);
insert into public.workspace_role_members(role_id,user_id) values ('00000000-0000-4000-8000-000000009113','00000000-0000-4000-8000-000000009103');
insert into public.workspace_meetings(id,ws_id,creator_id,name) values ('00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009102','Legacy meeting'),('00000000-0000-4000-8000-000000009122','00000000-0000-4000-8000-000000009111','00000000-0000-4000-8000-000000009102','Deletable meeting');
insert into public.recording_sessions(id,meeting_id,user_id) values ('00000000-0000-4000-8000-000000009124','00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009102'),('00000000-0000-4000-8000-000000009123','00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009102');
insert into public.audio_chunks(id,session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009125','00000000-0000-4000-8000-000000009124',0,'synthetic/chunk.webm');
insert into public.recording_sessions(id,meeting_id,user_id) values ('00000000-0000-4000-8000-000000009130','00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009104');
insert into public.audio_chunks(id,session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009131','00000000-0000-4000-8000-000000009130',0,'synthetic/member.webm');
select ok(not has_table_privilege('anon','public.workspace_meetings','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'anon has no workspace_meetings privileges');
select ok(not has_table_privilege('authenticated','public.workspace_meetings','TRUNCATE,REFERENCES,TRIGGER'), 'members cannot bypass workspace_meetings RLS with table privileges');
select ok(has_table_privilege('service_role','public.workspace_meetings','SELECT,INSERT,UPDATE,DELETE'), 'service role retains workspace_meetings operations');
select ok(not has_table_privilege('anon','public.recording_sessions','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'anon has no recording_sessions privileges');
select ok(not has_table_privilege('authenticated','public.recording_sessions','TRUNCATE,REFERENCES,TRIGGER'), 'members cannot bypass recording_sessions RLS with table privileges');
select ok(has_table_privilege('service_role','public.recording_sessions','SELECT,INSERT,UPDATE,DELETE'), 'service role retains recording_sessions operations');
select ok(not has_table_privilege('anon','public.audio_chunks','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'), 'anon has no audio_chunks privileges');
select ok(not has_table_privilege('authenticated','public.audio_chunks','TRUNCATE,REFERENCES,TRIGGER'), 'members cannot bypass audio_chunks RLS with table privileges');
select ok(has_table_privilege('service_role','public.audio_chunks','SELECT,INSERT,UPDATE,DELETE'), 'service role retains audio_chunks operations');
