select ok(not has_table_privilege('authenticated','private.recording_transcripts','SELECT'), 'legacy transcripts stay service-only');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009104","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select ok(not public.has_workspace_permission('00000000-0000-4000-8000-000000009111',auth.uid(),'admin'), 'ordinary member fixture has no admin permission');
select results_eq($$select name from public.workspace_meetings where id='00000000-0000-4000-8000-000000009121'$$, array['Legacy meeting'], 'member meeting read survives');
select results_eq($$select id::text from public.recording_sessions where id='00000000-0000-4000-8000-000000009124'$$, array['00000000-0000-4000-8000-000000009124'], 'member recording read survives');
select is_empty($$select id::text from public.audio_chunks where id='00000000-0000-4000-8000-000000009125'$$, 'member who did not record cannot list another recorders audio');
select is_empty($$update public.workspace_meetings set name='unauthorized' where id='00000000-0000-4000-8000-000000009121' returning id$$, 'member cannot update workspace_meetings');
select is_empty($$delete from public.workspace_meetings where id='00000000-0000-4000-8000-000000009121' returning id$$, 'member cannot delete workspace_meetings');
select is_empty($$update public.recording_sessions set status='failed' where id='00000000-0000-4000-8000-000000009124' returning id$$, 'member cannot update recording_sessions');
select is_empty($$delete from public.recording_sessions where id='00000000-0000-4000-8000-000000009124' returning id$$, 'member cannot delete recording_sessions');
select throws_ok($$insert into public.recording_sessions(meeting_id,user_id) values ('00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009102')$$,'42501',null,'member cannot spoof recording owner');
select results_eq($$insert into public.recording_sessions(meeting_id,user_id) values ('00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009104') returning user_id::text$$, array['00000000-0000-4000-8000-000000009104'], 'member can create own recording');
select throws_ok($$insert into public.audio_chunks(session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009124',99,'synthetic/denied.webm')$$,'42501',null,'member cannot upload to another creators recording');
select is_empty($$update public.audio_chunks set storage_path='synthetic/denied.webm' where id='00000000-0000-4000-8000-000000009125' returning id$$,'member cannot modify another creators chunk');
select is_empty($$delete from public.audio_chunks where id='00000000-0000-4000-8000-000000009125' returning id$$,'member cannot delete another creators chunk');
select results_eq($$update public.audio_chunks set storage_path='synthetic/member-updated.webm' where id='00000000-0000-4000-8000-000000009131' returning storage_path$$,array['synthetic/member-updated.webm'],'ordinary member can update own recording chunk');
select throws_ok($$update public.audio_chunks set session_id='00000000-0000-4000-8000-000000009124' where id='00000000-0000-4000-8000-000000009131'$$,'42501',null,'member cannot move an owned chunk into another creators recording');
select throws_ok($$truncate public.recording_sessions cascade$$,'42501',null,'TRUNCATE cannot bypass creator policy');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009102","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select results_eq($$update public.workspace_meetings set name='Creator rename' where id='00000000-0000-4000-8000-000000009121' returning name$$, array['Creator rename'], 'meeting creator can update');
select results_eq($$update public.recording_sessions set status='pending_transcription' where id='00000000-0000-4000-8000-000000009124' returning status::text$$, array['pending_transcription'], 'recording creator can stop');
select results_eq($$insert into public.recording_sessions(id,meeting_id,user_id) values ('00000000-0000-4000-8000-000000009129','00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009102') returning id::text$$,array['00000000-0000-4000-8000-000000009129'],'recording creator can insert');
select results_eq($$delete from public.recording_sessions where id='00000000-0000-4000-8000-000000009129' returning id::text$$,array['00000000-0000-4000-8000-000000009129'],'recording creator can delete');
select results_eq($$insert into public.audio_chunks(id,session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009132','00000000-0000-4000-8000-000000009124',1,'synthetic/creator.webm') returning id::text$$,array['00000000-0000-4000-8000-000000009132'],'recording creator can upload audio');
select results_eq($$update public.audio_chunks set storage_path='synthetic/creator-updated.webm' where id='00000000-0000-4000-8000-000000009125' returning storage_path$$,array['synthetic/creator-updated.webm'],'recording creator can update audio');
select results_eq($$delete from public.audio_chunks where id='00000000-0000-4000-8000-000000009132' returning id::text$$,array['00000000-0000-4000-8000-000000009132'],'recording creator can delete audio');
select throws_ok($$update public.recording_sessions set user_id='00000000-0000-4000-8000-000000009104' where id='00000000-0000-4000-8000-000000009124'$$,'42501','Recording identity is immutable','creator cannot transfer recording identity');
select throws_ok($$update public.recording_sessions set meeting_id='00000000-0000-4000-8000-000000009122' where id='00000000-0000-4000-8000-000000009124'$$,'42501','Recording identity is immutable','creator cannot move recording to another meeting');
select throws_ok($$update public.workspace_meetings set creator_id='00000000-0000-4000-8000-000000009104' where id='00000000-0000-4000-8000-000000009121'$$,'42501','Meeting creator is immutable','meeting host remains immutable');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009103","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select ok(public.has_workspace_permission('00000000-0000-4000-8000-000000009111',auth.uid(),'admin'), 'explicit admin fixture has admin permission');
select results_eq($$insert into public.audio_chunks(id,session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009133','00000000-0000-4000-8000-000000009124',2,'synthetic/admin.webm') returning id::text$$,array['00000000-0000-4000-8000-000000009133'],'workspace admin can upload audio');
select results_eq($$update public.audio_chunks set storage_path='synthetic/admin-updated.webm' where id='00000000-0000-4000-8000-000000009125' returning storage_path$$,array['synthetic/admin-updated.webm'],'workspace admin can update another creators audio');
select results_eq($$delete from public.audio_chunks where id='00000000-0000-4000-8000-000000009133' returning id::text$$,array['00000000-0000-4000-8000-000000009133'],'workspace admin can delete another creators audio');
select results_eq($$update public.workspace_meetings set name='Admin rename' where id='00000000-0000-4000-8000-000000009121' returning name$$, array['Admin rename'], 'workspace admin can update meeting');
select results_eq($$update public.recording_sessions set status='completed' where id='00000000-0000-4000-8000-000000009124' returning status::text$$, array['completed'], 'workspace admin can update another creators recording');
select results_eq($$delete from public.recording_sessions where id='00000000-0000-4000-8000-000000009123' returning id::text$$, array['00000000-0000-4000-8000-000000009123'], 'workspace admin can delete recording');
select results_eq($$delete from public.workspace_meetings where id='00000000-0000-4000-8000-000000009122' returning id::text$$, array['00000000-0000-4000-8000-000000009122'], 'workspace admin can delete meeting');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009105","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select is_empty($$select id from public.workspace_meetings where id='00000000-0000-4000-8000-000000009121'$$, 'other workspace admin cannot read workspace_meetings');
select is_empty($$select id from public.recording_sessions where id='00000000-0000-4000-8000-000000009124'$$, 'other workspace admin cannot read recording_sessions');
select is_empty($$select id from public.audio_chunks where id='00000000-0000-4000-8000-000000009125'$$, 'other workspace admin cannot read audio_chunks');
select is_empty($$update public.recording_sessions set status='failed' where id='00000000-0000-4000-8000-000000009124' returning id$$, 'other workspace admin cannot update recording');
select throws_ok($$insert into public.recording_sessions(meeting_id,user_id) values ('00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009105')$$,'42501',null,'other workspace admin cannot insert recording');
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009106","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select is_empty($$select id from public.workspace_meetings where id='00000000-0000-4000-8000-000000009121'$$, 'guest cannot read workspace_meetings');
select is_empty($$select id from public.recording_sessions where id='00000000-0000-4000-8000-000000009124'$$, 'guest cannot read recording_sessions');
select is_empty($$select id from public.audio_chunks where id='00000000-0000-4000-8000-000000009125'$$, 'guest cannot read audio_chunks');
select is_empty($$update public.recording_sessions set status='failed' where id='00000000-0000-4000-8000-000000009124' returning id$$, 'guest cannot update recording');
select throws_ok($$insert into public.recording_sessions(meeting_id,user_id) values ('00000000-0000-4000-8000-000000009121','00000000-0000-4000-8000-000000009106')$$,'42501',null,'guest cannot insert recording');
reset role;
select set_config('request.jwt.claims','{}',true);
delete from public.workspace_members where ws_id='00000000-0000-4000-8000-000000009111' and user_id='00000000-0000-4000-8000-000000009102';
reset role;
select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009102","role":"authenticated","aal":"aal2"}',true);
set local role authenticated;
select is_empty($$update public.audio_chunks set storage_path='synthetic/removed.webm' where id='00000000-0000-4000-8000-000000009125' returning id$$,'removed recording creator cannot update audio');
select throws_ok($$insert into public.audio_chunks(session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009124',99,'synthetic/removed.webm')$$,'42501',null,'removed recording creator cannot upload audio');
select is_empty($$update public.workspace_meetings set name='removed' where id='00000000-0000-4000-8000-000000009121' returning id$$, 'removed meeting creator cannot update');
select is_empty($$update public.recording_sessions set status='failed' where id='00000000-0000-4000-8000-000000009124' returning id$$, 'removed recording creator cannot update');
reset role;
set local role anon;
select throws_ok($$select * from public.audio_chunks$$,'42501',null,'anon cannot read audio');
select throws_ok($$insert into public.audio_chunks(session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009124',1,'synthetic')$$,'42501',null,'anon cannot write audio');
reset role;
set local role service_role;
select results_eq($$update public.recording_sessions set status='failed' where id='00000000-0000-4000-8000-000000009124' returning status::text$$, array['failed'], 'service role processing remains allowed');
reset role;
set local role service_role;
select results_eq($$insert into public.audio_chunks(id,session_id,chunk_order,storage_path) values ('00000000-0000-4000-8000-000000009134','00000000-0000-4000-8000-000000009124',3,'synthetic/service.webm') returning id::text$$,array['00000000-0000-4000-8000-000000009134'],'service processing can write audio');
reset role;
select * from finish();
rollback;
